    func worldAction(_ action:String)->Bool {
        guard career != nil else{return false}
        if action.hasPrefix("office:"),let mode=Int(action.dropFirst(7)),(0...2).contains(mode){officeMode=mode;officePage=0;return true}
        if action.hasPrefix("story:"),let mode=Int(action.dropFirst(6)),(0...1).contains(mode){storyMode=mode;storyPage=0;return true}
        for prefix in ["worldplayer:","releasecheck:","offerplayer:"] where action.hasPrefix(prefix){let id=String(action.dropFirst(prefix.count));guard let p=career?.player(id) else{return true};career?.prepareWorld();modal=action;focus=0;if prefix=="offerplayer:"{offerSalary=career!.annualAsk(p);offerYears=1;offerRole=career!.defaultRole(p)};return true}
        if action.hasPrefix("releasedo:"){let reply=career!.releasePlayer(String(action.dropFirst(10)));save();notify(reply);if reply.hasPrefix("RELEASED"){modal="";tab=19;officeMode=0};return true}
        if action.hasPrefix("worldpromise:"){let fields=action.split(separator:":",maxSplits:2);if fields.count==3,let role=Int(fields[1]){_=career?.promiseRole(String(fields[2]),role);save()};return true}
        if action.hasPrefix("worldstyle:"),let style=Int(action.dropFirst(11)),(0...3).contains(style){career?.prepareWorld();career!.world!.styles[career!.user]=style;save();return true}
        if action.hasPrefix("offersalary:"),let delta=Int(action.dropFirst(12)){offerSalary=max(1200,min(100000,offerSalary+delta));return true}
        if action.hasPrefix("offersubmit:"){let reply=career!.submitBid(MarketBid(player:String(action.dropFirst(12)),club:career!.user,salary:offerSalary,years:offerYears,role:offerRole));save();notify(reply);return true}
        if action.hasPrefix("offerwithdraw:"){let id=String(action.dropFirst(14)),owner=career!.user;career!.world?.winter?.bids.removeAll{$0.club==owner && $0.player==id};save();return true}
        if action.hasPrefix("eventchoice:"),let choice=Int(action.dropFirst(12)){if career!.resolveMoment(choice){save();modal="";notify("Club decision applied. Review League News for the result.")}else{notify("This choice requires sufficient cash and, for mentorship, a veteran and a young player.")};return true}
        switch action {
        case "officeprev":officePage=max(0,officePage-1)
        case "officenext":officePage+=1
        case "storyprev":storyPage=max(0,storyPage-1)
        case "storynext":storyPage+=1
        case "worldback":modal=""
        case "worldstyle","worldevent","worldincoming":modal=action;focus=0
        case "offeryears":offerYears=offerYears%3+1
        case "offerrole":offerRole=(offerRole+1)%4
        case "incomingdecline":career!.world?.incoming=nil;save();modal=""
        case "incomingaccept":let reply=career!.acceptLeagueOffer();save();modal="";notify(reply)
        case "winteradvance":if career!.advanceOffseason(){save();modal="";officePage=0;selectedDay=career!.day;syncMonth()}
        case "automate:contracts":career!.world?.autoContracts.toggle();save()
        case "automate:events":career!.world?.autoEvents.toggle();save()
        default:return false
        };return true
    }
